const FILE_LIMIT = 50 * 1024 * 1024;
function num(v, fallback = 0) { const n = Number(v); return Number.isFinite(n) ? n : fallback; }
function clamp(v, a, b) { return Math.min(b, Math.max(a, v)); }
function fmt(n, d = 2) { return Number.isFinite(n) ? Number(n.toFixed(d)).toString() : "—"; }
function safeFilename(s) { return String(s || "result").replace(/[<>:"/\\|?*\u0000-\u001F]/g, "-").trim().slice(0, 80) || "result"; }
function escapeHtml(value) { return String(value ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;"); }
function downloadText(name, text, type = "text/plain") { return downloadBlob(new Blob([text], { type }), safeFilename(name)); }
async function copy(text) { try { await navigator.clipboard.writeText(text); return true; } catch { return false; } }
function Notice({ children }) { return <p className="text-xs leading-5 text-navy-500 dark:text-navy-400">{children}</p>; }
function Result({ children }) { return <div className="rounded-2xl bg-brand-50 p-5 text-center text-lg font-bold text-brand-800 dark:bg-brand-950/30 dark:text-brand-200">{children}</div>; }
function Shell({ children, onReset }) { return <div className="space-y-5">{children}<div className="flex flex-wrap gap-2"><button type="button" className="mz-btn-ghost" onClick={onReset}><RotateCcw className="h-4 w-4"/>Reset</button></div></div>; }
function Input({ label, value, onChange, type="number", ...props }) { return <label className="text-sm font-semibold text-navy-800 dark:text-navy-100">{label}<input className="mz-input mt-2" type={type} value={value} onChange={e=>onChange(e.target.value)} {...props}/></label>; }

