 data: { bit:{name:"Bit",f:1/8}, byte:{name:"Byte",f:1}, kb:{name:"KB",f:1024}, mb:{name:"MB",f:1024**2}, gb:{name:"GB",f:1024**3}, tb:{name:"TB",f:1024**4} },
